def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_opp = history[-1][1]
    last_me = history[-1][0]

    opp_defects = sum(1 for h in history if h[1] == 'D')
    my_defects = sum(1 for h in history if h[0] == 'D')

    retaliations = 0
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i+1][1] == 'D':
            retaliations += 1

    if last_opp == 'D':
        if opp_defects > n * 0.8:
            return 'D'
        if rng.random() < 0.15:
            return 'C'
        return 'D'
    else:
        if retaliations > 0:
            return 'C'
        if my_defects > 0:
            if n % 2 == 0:
                return 'D'
            else:
                return 'C'
        else:
            if n < 6:
                return 'C'
            else:
                return 'D'
